-- ===========================================
-- Blanket postprocessing
-- ===========================================

-- Blanket spawnMask update for ALL creatures in classic dungeon maps
UPDATE `creature` SET `spawnMask` = 7
WHERE `map` IN (33, 34, 36, 43, 47, 48, 70, 90, 109, 129, 189, 209, 229, 230, 289, 329, 349, 389, 429)
AND `spawnMask` != 7;

-- Blanket creature_template_model copy for heroic clones (difficulty_entry_1)
INSERT IGNORE INTO `creature_template_model` (`CreatureID`, `Idx`, `CreatureDisplayID`, `DisplayScale`, `Probability`, `VerifiedBuild`)
SELECT ct_base.difficulty_entry_1, ctm.`Idx`, ctm.`CreatureDisplayID`, ctm.`DisplayScale`, ctm.`Probability`, ctm.`VerifiedBuild`
FROM creature_template ct_base
JOIN creature_template_model ctm ON ctm.CreatureID = ct_base.entry
WHERE ct_base.difficulty_entry_1 >= 9100000 AND ct_base.difficulty_entry_1 <= 9102593;

-- Blanket creature_template_model copy for mythic clones (difficulty_entry_2)
INSERT IGNORE INTO `creature_template_model` (`CreatureID`, `Idx`, `CreatureDisplayID`, `DisplayScale`, `Probability`, `VerifiedBuild`)
SELECT ct_base.difficulty_entry_2, ctm.`Idx`, ctm.`CreatureDisplayID`, ctm.`DisplayScale`, ctm.`Probability`, ctm.`VerifiedBuild`
FROM creature_template ct_base
JOIN creature_template_model ctm ON ctm.CreatureID = ct_base.entry
WHERE ct_base.difficulty_entry_2 >= 9100000 AND ct_base.difficulty_entry_2 <= 9102593;

